import React, { useEffect, useState } from "react"
import Link from "next/link"
import { useRouter } from "next/navigation"
import QuickSearch from "./QuickSearch"
import QuickTags from "./QuickTags"
import fetcher from "../lib/fetcher"
import styles from "../styles/dashboard.module.css"

// ──────────────────────────────────────────────
// 型定義
// ──────────────────────────────────────────────

type Article = {
  id: number | string
  title: string
  excerpt?: string
  author?: string
  publishedAt?: string
  updatedAt?: string
}

type SummaryData = {
  pendingCount?: number
  weeklyViews?: number
  weeklyPosts?: number
  weeklyComments?: number
  totalKnowledge?: number
}

type ArticleApiResponse = {
  content?: Article[]
  data?: Article[]
} | Article[]

// ──────────────────────────────────────────────
// サブコンポーネント: 記事カード
// ──────────────────────────────────────────────

function ArticleCard({ article, href }: { article: Article | null; href: string; loading?: boolean }) {
  if (!article) return null
  return (
    <div className={styles.articleCard}>
      <Link href={href} className={styles.articleCardLink}>
        {article.title}
      </Link>
      {article.excerpt && <p className={styles.articleCardExcerpt}>{article.excerpt}</p>}
      <div className={styles.articleCardMeta}>
        {article.author && <span>作成者: {article.author}</span>}
        {article.publishedAt && (
          <span>{new Date(article.publishedAt).toLocaleDateString("ja-JP")}</span>
        )}
      </div>
    </div>
  )
}

// ──────────────────────────────────────────────
// サイドバーナビゲーション
// ──────────────────────────────────────────────

const NAV_ITEMS = [
  { href: "/dashboard",         label: "ダッシュボード", icon: "🏠" },
  { href: "/dashboard/knowledge", label: "ナレッジ",     icon: "📚" },
  { href: "/dashboard/review",  label: "承認",           icon: "✅" },
  { href: "/dashboard/admin",   label: "管理者パネル",   icon: "⚙️" },
]

function Sidebar({ pendingCount }: { pendingCount: number | null }) {
  return (
    <aside className={styles.sidebar} aria-label="サイドナビゲーション">
      <span className={styles.navLabel}>メニュー</span>
      <nav>
        {NAV_ITEMS.map((item) => (
          <Link key={item.href} href={item.href} className={styles.navItem}>
            <span className={styles.navIcon} aria-hidden="true">{item.icon}</span>
