export default function Dashboard() {
  const router = useRouter()

  // クイック操作の選択状態（新着 or おすすめ）
  const [activeMode, setActiveMode] = useState<"latest" | "recommended">("latest")

  // 記事データ
  const [latestArticle, setLatestArticle] = useState<Article | null>(null)
  const [recommendedArticle, setRecommendedArticle] = useState<Article | null>(null)
  const [articlesLoading, setArticlesLoading] = useState(true)
  const [articlesError, setArticlesError] = useState<string | null>(null)

  // サマリーデータ（承認待ち・週次アクティビティ）
  const [summary, setSummary] = useState<SummaryData | null>(null)
  const [summaryLoading, setSummaryLoading] = useState(true)

  // 記事取得
  useEffect(() => {
    let cancelled = false
    async function loadArticles() {
      try {
        const [latestRes, recommendedRes] = await Promise.all([
          fetcher<ArticleApiResponse>("/api/v1/knowledge?sort=publishedAt,desc&size=1"),
          fetcher<ArticleApiResponse>("/api/v1/knowledge?sort=views,desc&size=1"),
        ])
        if (cancelled) return

        const toFirst = (res: ArticleApiResponse): Article | null => {
          const arr = Array.isArray(res)
            ? res
            : (res as { content?: Article[]; data?: Article[] }).content ??
              (res as { content?: Article[]; data?: Article[] }).data ??
              []
          return arr[0] ?? null
        }

        setLatestArticle(toFirst(latestRes))
        setRecommendedArticle(toFirst(recommendedRes))
      } catch {
        if (!cancelled) setArticlesError("記事の取得に失敗しました。")
      } finally {
        if (!cancelled) setArticlesLoading(false)
      }
    }
    loadArticles()
    return () => { cancelled = true }
  }, [])

  // サマリー取得
  useEffect(() => {
    let cancelled = false
    async function loadSummary() {
      try {
        const res = await fetcher<SummaryData>("/api/v1/summary")
        if (!cancelled) setSummary(res)
      } catch {
        // サマリー取得失敗はサイレント（ダッシュボードは部分表示可）
      } finally {
        if (!cancelled) setSummaryLoading(false)
      }
    }
    loadSummary()
    return () => { cancelled = true }
  }, [])

  const pendingCount = summary?.pendingCount ?? null

  return (
    <div className={styles.shell}>
      {/* ── サイドバー ── */}
      <Sidebar pendingCount={pendingCount} />

      {/* ── メインコンテンツ ── */}
      <main className={styles.main} id="main-content" aria-label="ダッシュボード メインコンテンツ">

        {/* ページタイトル */}
        <div>
          <h1 className={styles.pageTitle}>ダッシュボード</h1>
          <p className={styles.subTitle}>AIナレッジ共有プラットフォームへようこそ</p>
        </div>

        {/* ── セクション: クイック検索 ── */}
        <section aria-labelledby="section-search">
          <h2 className={styles.sectionTitle} id="section-search">知識を検索する</h2>
          <QuickSearch />
        </section>

        {/* ── セクション: クイック操作 ── */}
        <section aria-labelledby="section-quick-action">
          <h2 className={styles.sectionTitle} id="section-quick-action">クイック操作</h2>
          <div className={styles.quickActions}>
            <button
              type="button"
              className={`${styles.quickActionBtn} ${activeMode === "latest" ? styles.quickActionBtnActive : ""}`}
              onClick={() => setActiveMode("latest")}
              aria-pressed={activeMode === "latest"}
            >
              新着
            </button>
            <button
              type="button"
              className={`${styles.quickActionBtn} ${activeMode === "recommended" ? styles.quickActionBtnActive : ""}`}
              onClick={() => setActiveMode("recommended")}
              aria-pressed={activeMode === "recommended"}
            >
              おすすめ
            </button>
          </div>
        </section>

        {/* ── セクション: 記事エリア ── */}
        <section aria-labelledby="section-articles">
          <h2 className={styles.sectionTitle} id="section-articles">
            {activeMode === "latest" ? "新着記事" : "おすすめ記事"}
          </h2>
          {articlesLoading && <p className={styles.loadingText}>記事を読み込み中...</p>}
          {articlesError && <p className={styles.errorText}>{articlesError}</p>}
          {!articlesLoading && !articlesError && (
            <div className={styles.articleSectionGrid}>
              <div>
                <p className={styles.subTitle} style={{ marginBottom: "12px" }}>おすすめ記事</p>
                {recommendedArticle ? (
                  <ArticleCard
                    article={recommendedArticle}
                    href={`/knowledge/${recommendedArticle.id}`}
                  />
                ) : (
                  <p className={styles.loadingText}>おすすめ記事がありません。</p>
                )}
              </div>
              <div>
                <p className={styles.subTitle} style={{ marginBottom: "12px" }}>新着記事</p>
                {latestArticle ? (
                  <ArticleCard
                    article={latestArticle}
                    href={`/knowledge/${latestArticle.id}`}
                  />
                ) : (
                  <p className={styles.loadingText}>新着記事がありません。</p>
                )}
              </div>
            </div>
          )}
        </section>

        {/* ── セクション: 統計（承認待ち + 週次アクティビティ）── */}
        <section aria-labelledby="section-stats">
          <h2 className={styles.sectionTitle} id="section-stats">概要</h2>
          {summaryLoading && <p className={styles.loadingText}>データを読み込み中...</p>}
          {!summaryLoading && (
            <div className={styles.statsRow}>
              <div className={styles.statCard}>
                <p className={styles.statLabel}>承認待ち</p>
                <p className={styles.statValue}>
                  {summary?.pendingCount ?? "—"}
                </p>
                <p className={styles.statSub}>件のナレッジが承認待ちです</p>
                {pendingCount != null && pendingCount > 0 && (
                  <div style={{ marginTop: "8px" }}>
                    <span className={styles.pendingBadge}>
                      ⏳ {pendingCount} 件確認待ち
                    </span>
                  </div>
                )}
              </div>
              <div className={styles.statCard}>
                <p className={styles.statLabel}>今週の閲覧数</p>
                <p className={styles.statValue}>{summary?.weeklyViews ?? "—"}</p>
                <p className={styles.statSub}>先週比を確認してください</p>
              </div>
              <div className={styles.statCard}>
                <p className={styles.statLabel}>今週の投稿数</p>
                <p className={styles.statValue}>{summary?.weeklyPosts ?? "—"}</p>
                <p className={styles.statSub}>件のナレッジが投稿されました</p>
              </div>
              <div className={styles.statCard}>
                <p className={styles.statLabel}>ナレッジ総数</p>
                <p className={styles.statValue}>{summary?.totalKnowledge ?? "—"}</p>
                <p className={styles.statSub}>件のナレッジが蓄積されています</p>
              </div>
            </div>
          )}
        </section>

        {/* ── セクション: タグ一覧 ── */}
        <section aria-labelledby="section-tags">
          <h2 className={styles.sectionTitle} id="section-tags">タグから探す</h2>
          <QuickTags />
        </section>

      </main>
    </div>
  )
}
